// 1. Geometric path difference and constructive fringe condition
val pathDiffM = slitSeparationM * sin(thetaRad)
val isBrightFringe = abs((pathDiffM / wavelengthM) - orderM.toFloat()) < 0.08f

// 2. Screen fringe spacing and linear position of m-th bright fringe
val fringeSpacingM = (wavelengthM * screenDistanceM) / slitSeparationM
val fringePosY = orderM * fringeSpacingM
